//! The committed tune and held-out measure reports that the evidence-loop figure reads
//! are regenerated by the real commands and must match byte for byte.
use std::{path::PathBuf, process::Command};

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn sapho(args: &[&str]) -> Vec<u8> {
    let output = Command::new(env!("CARGO_BIN_EXE_sapho"))
        .args(args)
        .current_dir(root())
        .output()
        .expect("sapho runs");
    assert!(
        output.status.success(),
        "sapho {args:?}: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    output.stdout
}

fn assert_committed(report: &str, regenerated: &[u8]) {
    let committed = std::fs::read(root().join(report)).expect("committed report");
    assert!(
        committed == regenerated,
        "{report} is stale; regenerate it with `make reports`"
    );
}

const DATASET: [&str; 4] = [
    "--dataset",
    "examples/data/code-review-dataset.json",
    "--replay",
    "examples/recordings/code-review.json",
];

#[test]
fn committed_tune_report_matches_regeneration() {
    let mut args = vec![
        "tune",
        "--candidate",
        "examples/graphs/code-review.yaml",
        "--candidate",
        "examples/graphs/code-review-relaxed.yaml",
    ];
    args.extend(DATASET);
    args.extend(["--output-name", "needs_review", "--metric", "agreement"]);
    assert_committed("examples/reports/code-review-tune.json", &sapho(&args));
}

#[test]
fn committed_held_out_measure_report_matches_regeneration() {
    let mut args = vec!["measure", "examples/graphs/code-review.yaml"];
    args.extend(DATASET);
    args.extend(["--split", "held_out"]);
    assert_committed(
        "examples/reports/code-review-measure-held-out.json",
        &sapho(&args),
    );
}
